def attach_existing_inventory_to_stores(apps, schema_editor):
    Store = apps.get_model('products', 'Store')
    StoreVariantListing = apps.get_model('products', 'StoreVariantListing')
    VariantInventory = apps.get_model('products', 'VariantInventory')

    stores = {}
    for inventory in VariantInventory.objects.select_related('variant').iterator(chunk_size=500):
        if inventory.location not in stores:
            code, name = {
                'branch': ('main-shop', 'Main Shop'),
                'warehouse': ('pos-store', 'POS Store'),
            }[inventory.location]
            stores[inventory.location], _ = Store.objects.get_or_create(
                code=code,
                defaults={'name': name},
            )
        store = stores[inventory.location]
        listing, _ = StoreVariantListing.objects.get_or_create(
            store=store,
            variant=inventory.variant,
            defaults={
                'price': inventory.variant.price,
                'cost_price': inventory.variant.cost_price,
                'status': 'ACTIVE' if inventory.variant.is_active else 'INACTIVE',
                'is_active': inventory.variant.is_active,
                'raw_data': {'migrated_from_location': inventory.location},
            },
        )
        inventory.store_listing = listing
        inventory.save(update_fields=['store_listing'])


def detach_existing_inventory_from_stores(apps, schema_editor):
    StockMovement = apps.get_model('products', 'StockMovement')
    VariantInventory = apps.get_model('products', 'VariantInventory')

    # The old schema allowed only one row for a variant/location/batch. Merge
    # store-specific rows before restoring that constraint during rollback.
    keepers = {}
    for inventory in VariantInventory.objects.order_by('pk').iterator(chunk_size=500):
        key = (inventory.variant_id, inventory.location, inventory.batch_number)
        keeper = keepers.get(key)
        if keeper is None:
            inventory.store_listing = None
            inventory.save(update_fields=['store_listing'])
            keepers[key] = inventory
            continue

        keeper.stock_quantity += inventory.stock_quantity
        keeper.reorder_level += inventory.reorder_level
        keeper.low_stock_threshold += inventory.low_stock_threshold
        keeper.allow_backorder = keeper.allow_backorder or inventory.allow_backorder
        keeper.max_backorder_quantity += inventory.max_backorder_quantity
        if inventory.expiry_date and (
            keeper.expiry_date is None or inventory.expiry_date < keeper.expiry_date
        ):
            keeper.expiry_date = inventory.expiry_date
        keeper.is_pos_synced = keeper.is_pos_synced or inventory.is_pos_synced
        if inventory.last_synced_at and (
            keeper.last_synced_at is None or inventory.last_synced_at > keeper.last_synced_at
        ):
            keeper.last_synced_at = inventory.last_synced_at
        StockMovement.objects.filter(variant_inventory_id=inventory.pk).update(
            variant_inventory_id=keeper.pk
        )
        inventory.delete()
        keeper.save(update_fields=[
            'stock_quantity',
            'reorder_level',
            'low_stock_threshold',
            'allow_backorder',
            'max_backorder_quantity',
            'expiry_date',
            'is_pos_synced',
            'last_synced_at',
        ])


